class Course:
    def __init__(self, name, capacity):
        self.name = name
        self.capacity = capacity
        self.students = []
        self.waiting = []

    def enroll(self, student):
        if student in self.students or student in self.waiting:
            return "중복"
        if len(self.students) < self.capacity:
            self.students.append(student)
            return "등록"
        self.waiting.append(student)
        return "대기"

    def drop(self, student):
        if student in self.students:
            self.students.remove(student)
            if self.waiting:
                self.students.append(self.waiting.pop(0))
        elif student in self.waiting:
            self.waiting.remove(student)
        else:
            raise ValueError("없는 학생")

    def roster(self):
        return list(self.students)

    def waitlist(self):
        return list(self.waiting)

